import React, { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import axios from "axios";
import {
  Box,
  Typography,
  TextField,
  Button,
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableContainer,
  TableRow,
  Paper,
  Chip,
  IconButton,
  Card,
  CardContent,
  Grid,
  InputAdornment,
  Avatar,
  List,
  ListItem,
  ListItemIcon,
  ListItemText,
  Divider,
  Badge,
  useMediaQuery,
  useTheme,
  Drawer,
  FormControl,
  InputLabel,
  Select,
  MenuItem,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  CircularProgress,
} from "@mui/material";
import {
  Search,
  FilterList,
  Notifications,
  Circle,
  CheckCircle,
  Error,
  Warning,
  Chat,
  Delete,
  Visibility,
} from "@mui/icons-material";

const STATUS_OPTIONS = {
  New: "New",
  InProgress: "In Progress",
  Resolved: "Resolved",
  Closed: "Closed",
};

const PRIORITY_OPTIONS = ["High", "Medium", "Low"];

const DepartmentHeadDashboard = () => {
  const [searchQuery, setSearchQuery] = useState("");
  const [tickets, setTickets] = useState([]);
  const [notifications, setNotifications] = useState([]);
  const [notificationCount, setNotificationCount] = useState(0);
  const [ticketStats, setTicketStats] = useState({
    Resolved: 0,
    InProgress: 0,
    Pending: 0,
  });
  const [filterOpen, setFilterOpen] = useState(false);
  const [formData, setFormData] = useState({
    start_date: "",
    end_date: "",
    status: "",
    priority: "",
  });
  const [currentPage, setCurrentPage] = useState(1);
  const theme = useTheme();
  const isMobile = useMediaQuery(theme.breakpoints.down("sm"));
  const navigate = useNavigate();
  const [selectedTicket, setSelectedTicket] = useState(null);
  const [ticketDetails, setTicketDetails] = useState(null);
  const [dialogOpen, setDialogOpen] = useState(false);
  const [loadingDetails, setLoadingDetails] = useState(false);
  const token =
    typeof window !== "undefined" ? localStorage.getItem("token") : null;

  // Check if any filter is applied
  const isFilterApplied = Object.values(formData).some((value) => value !== "");

  // Fetch Tickets
  useEffect(() => {
    const fetchTickets = async () => {
      try {
        const params = { page: currentPage };
        if (isFilterApplied) {
          // Only include non-empty filter parameters
          if (formData.start_date) params.start_date = formData.start_date;
          if (formData.end_date) params.end_date = formData.end_date;
          if (formData.status) params.status = formData.status;
          if (formData.priority) params.priority = formData.priority;
        }
        const response = await axios.get(
          "https://support.mcdonalds.mu/api/ticket/list",
          {
            headers: { Authorization: `Bearer ${token}` },
            params,
          }
        );
        if (response.data.success) {
          setTickets(response.data.data.data);
          // Calculate ticket stats
          const stats = response.data.data.data.reduce(
            (acc, ticket) => {
              const statusKey =
                ticket.status === "Closed" || ticket.status === "Resolved"
                  ? "Resolved"
                  : ticket.status === "In Progress"
                  ? "InProgress"
                  : "Pending";
              acc[statusKey] = (acc[statusKey] || 0) + 1;
              return acc;
            },
            { Resolved: 0, InProgress: 0, Pending: 0 }
          );
          setTicketStats(stats);
        }
      } catch (error) {
        console.error("Error fetching tickets:", error);
      }
    };
    if (token) fetchTickets();
  }, [token, formData, currentPage, isFilterApplied]);

  // Fetch Notifications
  useEffect(() => {
    const fetchNotifications = async () => {
      try {
        const response = await axios.get(
          "https://support.mcdonalds.mu/api/notification/my?paginate=true",
          { headers: { Authorization: `Bearer ${token}` } }
        );
        if (response.data.success) {
          setNotifications(response.data.data.data);
          setNotificationCount(response.data.data.total);
        }
      } catch (error) {
        console.error("Error fetching notifications:", error);
      }
    };
    if (token) fetchNotifications();
  }, [token]);
  // Fetch Ticket Details
  const fetchTicketDetails = async (ticketId) => {
    setLoadingDetails(true);
    try {
      const response = await axios.get(
        `https://support.mcdonalds.mu/api/ticket/details/${ticketId}`,
        {
          headers: { Authorization: `Bearer ${token}` },
        }
      );
      if (response.data.success) {
        setTicketDetails(response.data.data);
      } else {
        setTicketDetails(null);
      }
    } catch (error) {
      console.error("Error fetching ticket details:", error);
      setTicketDetails(null);
    } finally {
      setLoadingDetails(false);
    }
  };
  const handleViewTicket = (ticket) => {
    setSelectedTicket(ticket);
    setDialogOpen(true);
    fetchTicketDetails(ticket.id);
  };

  const handleDialogClose = () => {
    setDialogOpen(false);
    setSelectedTicket(null);
    setTicketDetails(null);
  };

  const getPriorityColor = (priority) => {
    switch (priority) {
      case "High":
        return "#f44336";
      case "Medium":
        return "#ff9800";
      case "Low":
        return "#4caf50";
      default:
        return "#666666";
    }
  };

  const getStatusColor = (status) => {
    switch (status) {
      case "In Progress":
        return "#ff9800";
      case "Resolved":
      case "Closed":
        return "#4caf50";
      case "New":
      case "Pending":
        return "#f44336";
      default:
        return "#666666";
    }
  };

  const getNotificationIcon = (trigger_event) => {
    switch (trigger_event) {
      case "Ticket Created":
        return <CheckCircle sx={{ fontSize: { xs: 16, sm: 18 } }} />;
      case "Ticket Assigned":
        return <Warning sx={{ fontSize: { xs: 16, sm: 18 } }} />;
      default:
        return <Error sx={{ fontSize: { xs: 16, sm: 18 } }} />;
    }
  };

  const getNotificationColor = (trigger_event) => {
    switch (trigger_event) {
      case "Ticket Created":
        return "#4caf50";
      case "Ticket Assigned":
        return "#ff9800";
      default:
        return "#f44336";
    }
  };

  const handleInputChange = (e) => {
    const { name, value } = e.target;
    setFormData((prev) => ({ ...prev, [name]: value }));
  };

  const handleFilterOpen = () => setFilterOpen(true);
  const handleFilterClose = () => setFilterOpen(false);

  return (
    <Grid
      container
      rowSpacing={{ xs: 1, sm: 2, md: 2 }}
      columnSpacing={{ xs: 1, sm: 2, md: 2 }}
    >
      {/* Header with Search and Filters */}
      <Grid size={{ xs: 12, sm: 12, md: 12, lg: 12, xl: 12 }}>
        <Box
          sx={{
            display: "flex",
            flexDirection: { xs: "column", sm: "row" },
            justifyContent: "space-between",
            alignItems: { xs: "stretch", sm: "center" },
            mb: { xs: 1, sm: 2 },
            gap: { xs: 1, sm: 2 },
            px: 0,
          }}
        >
          <Box sx={{ flexGrow: 1, maxWidth: { xs: "100%", sm: 400 } }}>
            <TextField
              placeholder="Search tickets..."
              variant="outlined"
              size="small"
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              fullWidth
              sx={{
                "& .MuiOutlinedInput-root": {
                  borderRadius: 8,
                  backgroundColor: "#fff",
                  "& fieldset": { borderColor: "#e0e0e0" },
                  "&:hover fieldset": { borderColor: "#bdbdbd" },
                  "&.Mui-focused fieldset": { borderColor: "#4CAF50" },
                  "& input": {
                    padding: { xs: "6px 10px", sm: "8px 12px" },
                    fontSize: { xs: "0.75rem", sm: "0.875rem" },
                  },
                },
              }}
              InputProps={{
                startAdornment: (
                  <InputAdornment position="start">
                    <Search
                      sx={{ color: "#666", fontSize: { xs: 18, sm: 20 } }}
                    />
                  </InputAdornment>
                ),
              }}
            />
          </Box>
          <Box
            sx={{
              display: "flex",
              gap: 1,
              alignItems: "center",
              justifyContent: { xs: "space-between", sm: "flex-end" },
              width: { xs: "100%", sm: "auto" },
            }}
          >
            <Button
              variant="outlined"
              size="small"
              startIcon={<FilterList sx={{ fontSize: { xs: 16, sm: 18 } }} />}
              onClick={handleFilterOpen}
              sx={{
                borderColor: "#e0e0e0",
                color: "#333",
                borderRadius: 8,
                padding: { xs: "4px 8px", sm: "6px 12px" },
                textTransform: "none",
                fontWeight: 500,
                fontSize: { xs: "0.65rem", sm: "0.75rem" },
                "&:hover": {
                  borderColor: "#bdbdbd",
                  backgroundColor: "rgba(0, 0, 0, 0.04)",
                },
              }}
              aria-label="filter tickets"
            >
              Filter
            </Button>
          </Box>
        </Box>
      </Grid>

      {/* Filter Drawer */}
      <Drawer
        anchor="right"
        open={filterOpen}
        onClose={handleFilterClose}
        sx={{
          "& .MuiDrawer-paper": {
            width: { xs: "80%", sm: 300 },
            p: 2,
          },
        }}
      >
        <Box sx={{ p: 2 }}>
          <Typography
            variant="h6"
            sx={{ mb: 2, fontWeight: 500, color: "#1f2937" }}
          >
            Filter Tickets
          </Typography>
          <FormControl
            fullWidth
            size="small"
            variant="outlined"
            sx={{ mb: 2, minWidth: { xs: 150, sm: 200 } }}
          >
            <InputLabel>Status</InputLabel>
            <Select
              name="status"
              value={formData.status}
              onChange={handleInputChange}
              label="Status"
              sx={{
                "& .MuiSelect-select": {
                  fontSize: { xs: "0.875rem", sm: "1rem" },
                  padding: "8px 12px",
                },
                "& .MuiOutlinedInput-root": {
                  borderRadius: 2,
                  "& fieldset": { borderColor: "#e0e0e0" },
                  "&:hover fieldset": { borderColor: "#bdbdbd" },
                  "&.Mui-focused fieldset": { borderColor: "#4CAF50" },
                },
              }}
            >
              <MenuItem value="">All Statuses</MenuItem>
              {Object.entries(STATUS_OPTIONS).map(([key, value]) => (
                <MenuItem key={key} value={key}>
                  {value}
                </MenuItem>
              ))}
            </Select>
          </FormControl>
          <Typography
            variant="subtitle1"
            sx={{
              mb: 1,
              fontWeight: "medium",
              fontSize: { xs: "0.875rem", sm: "1rem" },
            }}
          >
            Date Range
          </Typography>
          <Box sx={{ display: "flex", gap: 1, mb: 2 }}>
            <TextField
              fullWidth
              name="start_date"
              label="Start Date"
              type="date"
              value={formData.start_date}
              onChange={handleInputChange}
              InputLabelProps={{ shrink: true }}
              size="small"
              sx={{
                "& .MuiOutlinedInput-root": {
                  borderRadius: 2,
                  "& fieldset": { borderColor: "#e0e0e0" },
                  "&:hover fieldset": { borderColor: "#bdbdbd" },
                  "&.Mui-focused fieldset": { borderColor: "#4CAF50" },
                  "& input": {
                    fontSize: { xs: "0.875rem", sm: "1rem" },
                    padding: "8px 12px",
                  },
                },
              }}
              InputProps={{ sx: { pr: 0 } }}
            />
            <TextField
              fullWidth
              name="end_date"
              label="End Date"
              type="date"
              value={formData.end_date}
              onChange={handleInputChange}
              InputLabelProps={{ shrink: true }}
              size="small"
              sx={{
                "& .MuiOutlinedInput-root": {
                  borderRadius: 2,
                  "& fieldset": { borderColor: "#e0e0e0" },
                  "&:hover fieldset": { borderColor: "#bdbdbd" },
                  "&.Mui-focused fieldset": { borderColor: "#4CAF50" },
                  "& input": {
                    fontSize: { xs: "0.875rem", sm: "1rem" },
                    padding: "8px 12px",
                  },
                },
              }}
              InputProps={{ sx: { pr: 0 } }}
            />
          </Box>
          <FormControl
            fullWidth
            size="small"
            variant="outlined"
            sx={{ mb: 2, minWidth: { xs: 150, sm: 200 } }}
          >
            <InputLabel>Priority</InputLabel>
            <Select
              name="priority"
              value={formData.priority}
              onChange={handleInputChange}
              label="Priority"
              sx={{
                "& .MuiSelect-select": {
                  fontSize: { xs: "0.875rem", sm: "1rem" },
                  padding: "8px 12px",
                },
                "& .MuiOutlinedInput-root": {
                  borderRadius: 2,
                  "& fieldset": { borderColor: "#e0e0e0" },
                  "&:hover fieldset": { borderColor: "#bdbdbd" },
                  "&.Mui-focused fieldset": { borderColor: "#4CAF50" },
                },
              }}
            >
              <MenuItem value="">All Priorities</MenuItem>
              {PRIORITY_OPTIONS.map((priority) => (
                <MenuItem key={priority} value={priority}>
                  {priority}
                </MenuItem>
              ))}
            </Select>
          </FormControl>
          <Box sx={{ display: "flex", gap: 1 }}>
            <Button
              variant="contained"
              color="success"
              onClick={handleFilterClose}
              sx={{ flex: 1, borderRadius: 6 }}
            >
              Apply
            </Button>
            <Button
              variant="outlined"
              onClick={() => {
                setFormData({
                  start_date: "",
                  end_date: "",
                  status: "",
                  priority: "",
                });
                handleFilterClose();
              }}
              sx={{ flex: 1, borderRadius: 6 }}
            >
              Clear
            </Button>
          </Box>
        </Box>
      </Drawer>

      {/* Tickets Table */}
      <Grid size={{ xs: 12, sm: 12, md: 12, lg: 12, xl: 12 }}>
        <Paper
          sx={{
            overflow: "hidden",
            boxShadow: "0 4px 12px rgba(0,0,0,0.1)",
          }}
        >
          <TableContainer
            sx={{
              maxHeight: 440,
            }}
          >
            <Table stickyHeader aria-label="sticky table">
              <TableHead>
                <TableRow sx={{ backgroundColor: "#f8f9fa" }}>
                  {[
                    { label: "ID" },
                    { label: "Title" },
                    { label: "Department" },
                    { label: "Location" },
                    { label: "Priority" },
                    { label: "Status" },
                    { label: "View" },
                  ].map((column) => (
                    <TableCell
                      key={column.label}
                      scope="col"
                      sx={{
                        fontWeight: 600,
                        backgroundColor: "#f8f9fa",
                        color: "#1f2937",
                        textOverflow:
                          column.label === "Title" ||
                          column.label === "Department" ||
                          column.label === "Location"
                            ? "ellipsis"
                            : "clip",
                        overflow:
                          column.label === "Title" ||
                          column.label === "Department" ||
                          column.label === "Location"
                            ? "hidden"
                            : "visible",
                        whiteSpace:
                          column.label === "Title" ||
                          column.label === "Department" ||
                          column.label === "Location"
                            ? "normal"
                            : "nowrap",
                      }}
                    >
                      {column.label}
                    </TableCell>
                  ))}
                </TableRow>
              </TableHead>
              <TableBody>
                {tickets.length === 0 ? (
                  <TableRow>
                    <TableCell colSpan={6} align="center">
                      <Typography
                        variant="body2"
                        sx={{ color: "#6b7280", py: 2 }}
                      >
                        No Data Available
                      </Typography>
                    </TableCell>
                  </TableRow>
                ) : (
                  tickets
                    .filter((ticket) =>
                      ticket.title
                        .toLowerCase()
                        .includes(searchQuery.toLowerCase())
                    )
                    .map((ticket) => (
                      <TableRow
                        key={ticket.id}
                        hover
                        sx={{ "&:hover": { backgroundColor: "#f1f5f9" } }}
                      >
                        <TableCell
                          scope="row"
                          sx={{
                            whiteSpace: "nowrap",
                          }}
                        >
                          {ticket.id}
                        </TableCell>
                        <TableCell
                          sx={{
                            textOverflow: "ellipsis",
                            overflow: "hidden",
                            whiteSpace: "normal",
                          }}
                        >
                          {ticket.title}
                        </TableCell>
                        <TableCell
                          sx={{
                            textOverflow: "ellipsis",
                            overflow: "hidden",
                            whiteSpace: "normal",
                          }}
                        >
                          {ticket.department.name}
                        </TableCell>
                        <TableCell
                          sx={{
                            textOverflow: "ellipsis",
                            overflow: "hidden",
                            whiteSpace: "normal",
                          }}
                        >
                          {ticket.location.name}
                        </TableCell>
                        <TableCell
                          sx={{
                            whiteSpace: "nowrap",
                          }}
                        >
                          <Chip
                            label={ticket.priority}
                            size="small"
                            sx={{
                              bgcolor: getPriorityColor(ticket.priority),
                              color: "#fff",
                            }}
                          />
                        </TableCell>
                        <TableCell
                          sx={{
                            whiteSpace: "nowrap",
                          }}
                        >
                          <Chip
                            label={ticket.status}
                            size="small"
                            sx={{
                              bgcolor: getStatusColor(ticket.status),
                              color: "#fff",
                            }}
                          />
                        </TableCell>
                        <TableCell
                          sx={{
                            whiteSpace: "nowrap",
                          }}
                        >
                          <IconButton
                            onClick={() => handleViewTicket(ticket)}
                            sx={{
                              color: "#43B02A",
                              "&:hover": { color: "#3a9c26" },
                            }}
                            aria-label={`view ticket ${ticket.id}`}
                          >
                            <Visibility fontSize="small" />
                          </IconButton>
                        </TableCell>
                      </TableRow>
                    ))
                )}
              </TableBody>
            </Table>
          </TableContainer>
        </Paper>
      </Grid>
      {/* Ticket Details Dialog */}
      <Dialog
        open={dialogOpen}
        onClose={handleDialogClose}
        maxWidth="lg"
        fullWidth
        sx={{
          "& .MuiDialog-paper": {
            borderRadius: 3,
            background: "linear-gradient(145deg, #ffffff, #f5f7fa)",
            boxShadow: "0 12px 24px rgba(0,0,0,0.15)",
            overflow: "hidden",
            maxWidth: { xs: "90%", sm: "600px" },
            p: { xs: 1, sm: 2 },
          },
        }}
      >
        <DialogTitle
          sx={{
            display: "flex",
            alignItems: "center",
            gap: 1,
            background: "linear-gradient(45deg, #43B02A 0%, #66BB6A 100%)",
            color: "#fff",
            fontWeight: 600,
            fontSize: { xs: "1.2rem", sm: "1.5rem" },
            p: 2,
            borderRadius: "12px 12px 0 0",
          }}
        >
          <Visibility sx={{ fontSize: { xs: 20, sm: 24 } }} />
          Ticket #{selectedTicket?.id || "N/A"}
        </DialogTitle>
        <DialogContent sx={{ p: { xs: 2, sm: 3 } }}>
          {loadingDetails ? (
            <Box
              sx={{
                display: "flex",
                justifyContent: "center",
                alignItems: "center",
                minHeight: 200,
              }}
            >
              <CircularProgress size={40} sx={{ color: "#43B02A" }} />
            </Box>
          ) : ticketDetails ? (
            <Box sx={{ display: "flex", flexDirection: "column", gap: 2.5 }}>
              <Paper
                elevation={1}
                sx={{
                  p: 2,
                  borderRadius: 2,
                  mt: 1,
                  backgroundColor: "#fafafa",
                  border: "1px solid #e0e0e0",
                }}
              >
                <Typography
                  variant="h6"
                  sx={{
                    fontWeight: 600,
                    color: "#1f2937",
                    mb: 2,
                    fontSize: { xs: "1rem", sm: "1.25rem" },
                  }}
                >
                  Ticket Information
                </Typography>
                <Grid container spacing={2}>
                  <Grid item xs={12} sm={6}>
                    <Typography
                      variant="subtitle2"
                      color="#666"
                      fontWeight={500}
                      sx={{ fontSize: { xs: "0.8rem", sm: "0.875rem" } }}
                    >
                      Title
                    </Typography>
                    <Typography
                      variant="body1"
                      sx={{
                        fontWeight: 500,
                        color: "#1f2937",
                        fontSize: { xs: "0.9rem", sm: "1rem" },
                      }}
                    >
                      {ticketDetails.title || "N/A"}
                    </Typography>
                  </Grid>
                  <Grid item xs={12} sm={6}>
                    <Typography
                      variant="subtitle2"
                      color="#666"
                      fontWeight={500}
                      sx={{ fontSize: { xs: "0.8rem", sm: "0.875rem" } }}
                    >
                      Priority
                    </Typography>
                    <Chip
                      label={ticketDetails.priority || "N/A"}
                      size="small"
                      sx={{
                        bgcolor: getPriorityColor(ticketDetails.priority),
                        color: "#fff",
                        fontWeight: 500,
                        fontSize: { xs: "0.75rem", sm: "0.875rem" },
                      }}
                    />
                  </Grid>
                  <Grid item xs={12} sm={6}>
                    <Typography
                      variant="subtitle2"
                      color="#666"
                      fontWeight={500}
                      sx={{ fontSize: { xs: "0.8rem", sm: "0.875rem" } }}
                    >
                      Status
                    </Typography>
                    <Chip
                      label={ticketDetails.status || "N/A"}
                      size="small"
                      sx={{
                        bgcolor: getStatusColor(ticketDetails.status),
                        color: "#fff",
                        fontWeight: 500,
                        fontSize: { xs: "0.75rem", sm: "0.875rem" },
                      }}
                    />
                  </Grid>
                  <Grid item xs={12} sm={6}>
                    <Typography
                      variant="subtitle2"
                      color="#666"
                      fontWeight={500}
                      sx={{ fontSize: { xs: "0.8rem", sm: "0.875rem" } }}
                    >
                      Reported By
                    </Typography>
                    <Typography
                      variant="body1"
                      sx={{
                        fontWeight: 500,
                        color: "#1f2937",
                        fontSize: { xs: "0.9rem", sm: "1rem" },
                      }}
                    >
                      {ticketDetails.submit_by?.name || "N/A"}
                    </Typography>
                  </Grid>
                  <Grid item xs={12} sm={6}>
                    <Typography
                      variant="subtitle2"
                      color="#666"
                      fontWeight={500}
                      sx={{ fontSize: { xs: "0.8rem", sm: "0.875rem" } }}
                    >
                      Department
                    </Typography>
                    <Typography
                      variant="body1"
                      sx={{
                        fontWeight: 500,
                        color: "#1f2937",
                        fontSize: { xs: "0.9rem", sm: "1rem" },
                      }}
                    >
                      {ticketDetails.department?.name || "N/A"}
                    </Typography>
                  </Grid>
                  <Grid item xs={12} sm={6}>
                    <Typography
                      variant="subtitle2"
                      color="#666"
                      fontWeight={500}
                      sx={{ fontSize: { xs: "0.8rem", sm: "0.875rem" } }}
                    >
                      Location
                    </Typography>
                    <Typography
                      variant="body1"
                      sx={{
                        fontWeight: 500,
                        color: "#1f2937",
                        fontSize: { xs: "0.9rem", sm: "1rem" },
                      }}
                    >
                      {ticketDetails.location?.name || "N/A"}
                    </Typography>
                  </Grid>
                  <Grid item xs={12}>
                    <Typography
                      variant="subtitle2"
                      color="#666"
                      fontWeight={500}
                      sx={{ fontSize: { xs: "0.8rem", sm: "0.875rem" } }}
                    >
                      Description
                    </Typography>
                    <Typography
                      variant="body1"
                      sx={{
                        fontWeight: 500,
                        color: "#1f2937",
                        fontSize: { xs: "0.9rem", sm: "1rem" },
                      }}
                    >
                      {ticketDetails.description || "N/A"}
                    </Typography>
                  </Grid>
                  <Grid item xs={12}>
                    <Typography
                      variant="subtitle2"
                      color="#666"
                      fontWeight={500}
                      sx={{ fontSize: { xs: "0.8rem", sm: "0.875rem" } }}
                    >
                      Issue
                    </Typography>
                    <Typography
                      variant="body1"
                      sx={{
                        fontWeight: 500,
                        color: "#1f2937",
                        fontSize: { xs: "0.9rem", sm: "1rem" },
                      }}
                    >
                      {ticketDetails.issue || "N/A"}
                    </Typography>
                  </Grid>
                  <Grid item xs={12} sm={6}>
                    <Typography
                      variant="subtitle2"
                      color="#666"
                      fontWeight={500}
                      sx={{ fontSize: { xs: "0.8rem", sm: "0.875rem" } }}
                    >
                      Assigned To
                    </Typography>
                    <Typography
                      variant="body1"
                      sx={{
                        fontWeight: 500,
                        color: "#1f2937",
                        fontSize: { xs: "0.9rem", sm: "1rem" },
                      }}
                    >
                      {ticketDetails.assign_to?.name || "Unassigned"}
                    </Typography>
                  </Grid>
                  <Grid item xs={12} sm={6}>
                    <Typography
                      variant="subtitle2"
                      color="#666"
                      fontWeight={500}
                      sx={{ fontSize: { xs: "0.8rem", sm: "0.875rem" } }}
                    >
                      Expected Resolution Time
                    </Typography>
                    <Typography
                      variant="body1"
                      sx={{
                        fontWeight: 500,
                        color: "#1f2937",
                        fontSize: { xs: "0.9rem", sm: "1rem" },
                      }}
                    >
                      {ticketDetails.expected_resolution_time
                        ? new Date(
                            ticketDetails.expected_resolution_time
                          ).toLocaleString()
                        : "N/A"}
                    </Typography>
                  </Grid>
                </Grid>
              </Paper>
              <Paper
                elevation={1}
                sx={{
                  p: 2,
                  borderRadius: 2,
                  backgroundColor: "#fafafa",
                  border: "1px solid #e0e0e0",
                }}
              >
                <Typography
                  variant="h6"
                  sx={{
                    fontWeight: 600,
                    color: "#1f2937",
                    mb: 2,
                    fontSize: { xs: "1rem", sm: "1.25rem" },
                  }}
                >
                  Comments
                </Typography>
                {ticketDetails.comment && ticketDetails.comment.length > 0 ? (
                  <Box sx={{ maxHeight: 250, overflowY: "auto" }}>
                    {ticketDetails.comment.map((comment) => (
                      <Paper
                        key={comment.id}
                        elevation={0}
                        sx={{
                          p: 1.5,
                          mb: 1,
                          borderRadius: 2,
                          backgroundColor: "#ffffff",
                          border: "1px solid #e0e0e0",
                          transition: "all 0.2s",
                          "&:hover": {
                            boxShadow: "0 2px 8px rgba(0,0,0,0.1)",
                          },
                        }}
                      >
                        <Box
                          sx={{
                            display: "flex",
                            alignItems: "center",
                            gap: 1,
                            mb: 0.5,
                          }}
                        >
                          <Avatar
                            sx={{
                              width: { xs: 24, sm: 28 },
                              height: { xs: 24, sm: 28 },
                              bgcolor: "#43B02A",
                              fontSize: { xs: "0.75rem", sm: "0.875rem" },
                            }}
                          >
                            {comment.user?.name?.charAt(0) || "U"}
                          </Avatar>
                          <Typography
                            variant="body2"
                            sx={{
                              fontWeight: 600,
                              color: "#1f2937",
                              fontSize: { xs: "0.85rem", sm: "0.9rem" },
                            }}
                          >
                            {comment.user?.name || "Unknown"}
                          </Typography>
                        </Box>
                        <Typography
                          variant="body2"
                          sx={{
                            color: "#1f2937",
                            fontSize: { xs: "0.85rem", sm: "0.9rem" },
                            mb: 0.5,
                          }}
                        >
                          {comment.comment || "N/A"}
                        </Typography>
                        <Typography
                          variant="caption"
                          sx={{
                            color: "#6b7280",
                            fontSize: { xs: "0.7rem", sm: "0.75rem" },
                          }}
                        >
                          {comment.created_at
                            ? new Date(comment.created_at).toLocaleString()
                            : "N/A"}
                        </Typography>
                      </Paper>
                    ))}
                  </Box>
                ) : (
                  <Typography
                    variant="body2"
                    sx={{
                      color: "#6b7280",
                      textAlign: "center",
                      py: 2,
                      fontSize: { xs: "0.85rem", sm: "0.9rem" },
                    }}
                  >
                    No comments available
                  </Typography>
                )}
              </Paper>
            </Box>
          ) : (
            <Typography
              variant="body2"
              sx={{
                color: "#6b7280",
                textAlign: "center",
                py: 4,
                fontSize: { xs: "0.9rem", sm: "1rem" },
              }}
            >
              No Data Available
            </Typography>
          )}
        </DialogContent>
        <DialogActions sx={{ p: 2, justifyContent: "center" }}>
          <Button
            onClick={handleDialogClose}
            variant="contained"
            sx={{
              backgroundColor: "#43B02A",
              color: "#fff",
              borderRadius: 6,
              textTransform: "none",
              fontWeight: 500,
              fontSize: { xs: "0.85rem", sm: "0.9rem" },
              px: 3,
              "&:hover": {
                backgroundColor: "#3a9c26",
                boxShadow: "0 2px 8px rgba(67, 176, 42, 0.3)",
              },
            }}
          >
            Close
          </Button>
        </DialogActions>
      </Dialog>

      {/* Tickets Status Card */}
      <Grid size={{ xs: 12, sm: 12, md: 6, lg: 6, xl: 6 }}>
        <Card
          sx={{
            height: "100%",
            display: "flex",
            flexDirection: "column",
            maxWidth: { xs: "100%", sm: 650 },
            width: "100%",
            boxSizing: "border-box",
          }}
        >
          <CardContent sx={{ p: { xs: 2, sm: 3 }, flexGrow: 1 }}>
            <Box
              sx={{
                display: "flex",
                alignItems: "center",
                justifyContent: "space-between",
                mb: 3,
                flexDirection: { xs: "column", sm: "row" },
                gap: 2,
              }}
            >
              <Typography
                variant="h6"
                sx={{
                  display: "flex",
                  alignItems: "center",
                  gap: 1,
                  color: "#1f2937",
                  fontWeight: 500,
                  fontSize: { xs: "18px", sm: "20px" },
                }}
              >
                <Circle
                  sx={{ color: "#4CAF50", fontSize: { xs: 12, sm: 14 } }}
                />
                Tickets Status
              </Typography>
            </Box>
            <Box
              sx={{
                display: "flex",
                alignItems: "center",
                justifyContent: "space-between",
                gap: { xs: 3, sm: 4 },
                // mb: 3,
                flexDirection: { xs: "column", sm: "row" },
              }}
            >
              <Typography
                variant="h2"
                sx={{
                  fontWeight: 700,
                  color: "#1f2937",
                  fontSize: { xs: "32px", sm: "62px" },
                  minWidth: { xs: "100px", sm: "120px" },
                  letterSpacing: 0.5,
                  textAlign: { xs: "center", sm: "center" },
                }}
              >
                {ticketStats.Resolved +
                  ticketStats.InProgress +
                  ticketStats.Pending}
              </Typography>
              <Box sx={{ flex: 1, width: "100%" }}>
                {[
                  {
                    label: "Resolved",
                    count: ticketStats.Resolved,
                    color: "#4caf50",
                  },
                  {
                    label: "In-progress",
                    count: ticketStats.InProgress,
                    color: "#ff9800",
                  },
                  {
                    label: "Pending",
                    count: ticketStats.Pending,
                    color: "#f44336",
                  },
                ].map((status) => (
                  <Box
                    key={status.label}
                    sx={{
                      display: "flex",
                      alignItems: "center",
                      justifyContent: "space-around",
                      mb: 1.5,
                    }}
                  >
                    <Box sx={{ display: "flex", alignItems: "center", gap: 1 }}>
                      <Circle
                        sx={{
                          color: status.color,
                          fontSize: { xs: 10, sm: 12 },
                        }}
                      />
                      <Typography
                        variant="body2"
                        sx={{
                          color: "#1f2937",
                          fontSize: { xs: "14px", sm: "16px" },
                        }}
                      >
                        {status.label}
                      </Typography>
                    </Box>
                    <Typography
                      variant="body2"
                      sx={{
                        fontWeight: 500,
                        color: "#1f2937",
                        fontSize: { xs: "14px", sm: "16px" },
                      }}
                    >
                      {status.count}
                    </Typography>
                  </Box>
                ))}
              </Box>
            </Box>
            {/* <Box
              sx={{
                display: "flex",
                justifyContent: "space-between",
                gap: 2,
                flexDirection: { xs: "column", sm: "row" },
              }}
            >
              <Button
                variant="contained"
                color="success"
                startIcon={
                  <CheckCircle sx={{ fontSize: { xs: 18, sm: 20 } }} />
                }
                size="small"
                sx={{
                  borderRadius: 8,
                  fontSize: { xs: "14px", sm: "16px" },
                  padding: { xs: "6px 12px", sm: "8px 16px" },
                  textTransform: "none",
                  flex: 1,
                }}
                aria-label="submit ticket"
              >
                Submit a Ticket
              </Button>
              <Button
                variant="outlined"
                size="small"
                onClick={() => navigate("/dashboard/my-tickets")}
                sx={{
                  borderColor: "#e0e0e0",
                  color: "#333",
                  "&:hover": {
                    borderColor: "#bdbdbd",
                    bgcolor: "rgba(0, 0, 0, 0.04)",
                  },
                  fontSize: { xs: "14px", sm: "16px" },
                  padding: { xs: "6px 12px", sm: "8px 16px" },
                  textTransform: "none",
                  flex: 1,
                }}
                aria-label="view my tickets"
              >
                View my Tickets
              </Button>
            </Box> */}
          </CardContent>
        </Card>
      </Grid>

      {/* Notifications Card */}
      <Grid size={{ xs: 12, sm: 12, md: 6, lg: 6, xl: 6 }}>
        <Card
          sx={{
            height: "100%",
            display: "flex",
            flexDirection: "column",
            maxWidth: { xs: "100%", sm: 650 },
            boxSizing: "border-box",
          }}
        >
          <CardContent sx={{ p: { xs: 1, sm: 2 }, flexGrow: 1 }}>
            <Box
              sx={{
                display: "flex",
                alignItems: "center",
                justifyContent: "space-between",
                mb: 2,
                flexDirection: { xs: "column", sm: "row" },
                gap: 1,
              }}
            >
              <Typography
                variant="h6"
                sx={{
                  display: "flex",
                  alignItems: "center",
                  gap: 1,
                  color: "#1f2937",
                  fontWeight: 500,
                }}
              >
                <Badge
                  badgeContent={notificationCount}
                  color="error"
                  sx={{
                    "& .MuiBadge-badge": {
                      fontSize: { xs: "0.55rem", sm: "0.65rem" },
                      height: { xs: 16, sm: 18 },
                      minWidth: { xs: 16, sm: 18 },
                      bgcolor: "#DA291C",
                    },
                  }}
                >
                  <Notifications sx={{ fontSize: { xs: 18, sm: 20 } }} />
                </Badge>
                Notifications
              </Typography>
            </Box>
            <List sx={{ maxHeight: 300, overflowY: "auto" }}>
              {notifications.length === 0 ? (
                <ListItem>
                  <ListItemText
                    primary={
                      <Typography
                        variant="body2"
                        sx={{
                          color: "#6b7280",
                          textAlign: "center",
                          py: 2,
                        }}
                      >
                        No Data Available
                      </Typography>
                    }
                  />
                </ListItem>
              ) : (
                notifications.map((notification, index) => (
                  <React.Fragment key={notification.id}>
                    <ListItem
                      sx={{
                        "&:hover": { backgroundColor: "#f1f5f9" },
                        borderRadius: 8,
                        mb: 1,
                        flexDirection: { xs: "column", sm: "row" },
                        alignItems: { xs: "flex-start", sm: "center" },
                        gap: { xs: 1, sm: 2 },
                        py: { xs: 0.5, sm: 1 },
                      }}
                    >
                      <ListItemIcon>
                        <Avatar
                          sx={{
                            bgcolor: getNotificationColor(
                              notification.trigger_event
                            ),
                            width: { xs: 24, sm: 28 },
                            height: { xs: 24, sm: 28 },
                          }}
                        >
                          {getNotificationIcon(notification.trigger_event)}
                        </Avatar>
                      </ListItemIcon>
                      <ListItemText
                        primary={
                          <Typography
                            variant="body2"
                            sx={{
                              fontWeight: 600,
                              color: "#1f2937",
                            }}
                          >
                            {notification.title}
                          </Typography>
                        }
                        secondary={
                          <>
                            <Typography
                              variant="caption"
                              display="block"
                              sx={{
                                color: "#6b7280",
                                maxWidth: { xs: "100%", sm: 500 },
                              }}
                            >
                              {notification.message}
                            </Typography>
                            <Typography
                              variant="caption"
                              sx={{
                                color: "#6b7280",
                              }}
                            >
                              {new Date(
                                notification.created_at
                              ).toLocaleString()}
                            </Typography>
                          </>
                        }
                      />
                    </ListItem>
                    {index < notifications.length - 1 && (
                      <Divider sx={{ bgcolor: "#e0e0e0" }} />
                    )}
                  </React.Fragment>
                ))
              )}
            </List>
          </CardContent>
        </Card>
      </Grid>
    </Grid>
  );
};

export default DepartmentHeadDashboard;
